<script setup>
import {ref,onMounted} from 'vue';
import {PRICING_PRESETS_KEY,MAX_PRICING_PRESETS_BYTES,validatePricingPresets,savePricingPreset,exportPricingPresets,importPricingPresets} from '../shared/pricing-presets.mjs';
const props=defineProps({current:Object}),emit=defineEmits(['apply']);
const presets=ref([]),name=ref(''),choice=ref(''),message=ref(''),storageError=ref(false);
function load(){try{const text=localStorage.getItem(PRICING_PRESETS_KEY);presets.value=validatePricingPresets(text?JSON.parse(text):[]);if(!presets.value.some(p=>p.id===choice.value))choice.value='';storageError.value=false;message.value='Pricing presets loaded';}catch(e){storageError.value=true;message.value='Cannot load pricing presets: '+e.message;}}
function commit(next){localStorage.setItem(PRICING_PRESETS_KEY,JSON.stringify(next));presets.value=next;}
function save(){try{const next=savePricingPreset(presets.value,{id:crypto.randomUUID(),name:name.value,pricing:props.current});commit(next);choice.value=next.find(p=>p.name.toLowerCase()===name.value.trim().toLowerCase()).id;message.value='Pricing preset saved';}catch(e){message.value=e.message;}}
function backup(){try{const url=URL.createObjectURL(new Blob([exportPricingPresets(presets.value)],{type:'application/json'})),link=document.createElement('a');link.href=url;link.download='terratec_pricing-presets.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),0);message.value='Pricing presets exported';}catch(e){message.value=e.message;}}
function apply(){const preset=presets.value.find(p=>p.id===choice.value);if(preset){emit('apply',validatePricingPresets([preset])[0].pricing);message.value='Pricing preset applied to draft rates';}}
function remove(){try{commit(presets.value.filter(p=>p.id!==choice.value));choice.value='';message.value='Pricing preset removed';}catch(e){message.value=e.message;}}
async function importFile(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;try{if(file.size>MAX_PRICING_PRESETS_BYTES)throw Error('Pricing preset file exceeds 128 KiB');const next=importPricingPresets(presets.value,await file.text());commit(next);message.value='Pricing presets imported';}catch(e){message.value=e.message;}}
onMounted(load);
</script>
<template><section aria-label="Workshop pricing presets"><h4>Workshop pricing presets</h4><p class="hint">Saved in this browser across projects. Includes currency, sheet, hardware, labour, markup and optional edging rates. Applying updates draft rates only. Export a backup to transfer presets.</p><button @click="load">Reload pricing presets</button><fieldset :disabled="storageError"><label>Pricing preset name<input v-model="name" maxlength="60"></label><button :disabled="!name.trim()||!current" @click="save">Save pricing preset</button><p class="hint">Saving the same name updates its rates.</p><label>Pricing preset<select v-model="choice" aria-label="Pricing preset"><option value="">Choose pricing preset</option><option v-for="preset in presets" :key="preset.id" :value="preset.id">{{ preset.name }}</option></select></label><button :disabled="!choice" @click="apply">Apply pricing preset</button><button :disabled="!choice" @click="remove">Remove pricing preset</button><button :disabled="!presets.length" @click="backup">Export pricing presets</button><label>Import pricing presets<input type="file" accept=".json,application/json" aria-label="Import pricing presets file" @change="importFile"></label><p class="hint">Imports merge with existing presets; name conflicts receive an import suffix.</p></fieldset><p data-testid="pricing-preset-message" role="status">{{ message }}</p></section></template>
